/* eslint-disable react-hooks/exhaustive-deps -- session scopes are ref-backed; project/stage scalars define invalidation */
import { createContext, useContext, useEffect, useRef, useState, type Dispatch, type ReactNode, type SetStateAction } from 'react';
import { useAppState } from '../../app/AppState';
import { Badge, Button, Card, CardHeader, Field, Input, Textarea } from '../../components/ui';
const tabs = ['Script', 'Native'] as const; type PromptTab = (typeof tabs)[number]; type SyntaxResult = 'idle' | 'valid' | 'invalid';
const operations=['Author','Review','Correct','Recheck','Media review'] as const;type Operation=(typeof operations)[number];
interface ExternalSession { tab: PromptTab; setTab: Dispatch<SetStateAction<PromptTab>>; json: string; setJson: Dispatch<SetStateAction<string>>; result: SyntaxResult; setResult: Dispatch<SetStateAction<SyntaxResult>> }
const Context = createContext<ExternalSession | null>(null);
export function ExternalSessionProvider({ children }: { children: ReactNode }) { const [tab,setTab]=useState<PromptTab>('Script'); const [json,setJson]=useState(''); const [result,setResult]=useState<SyntaxResult>('idle'); return <Context.Provider value={{tab,setTab,json,setJson,result,setResult}}>{children}</Context.Provider>; }
const useSession=()=>{const value=useContext(Context);if(!value)throw new Error('ExternalSessionProvider missing');return value;};
export function ExternalWorkspace(){
  const {tab,setTab,json,setJson,result,setResult}=useSession(); const {native,captureProjectSession,isCurrentProjectSession,setNativeIfSessionCurrent,showNotice}=useAppState(); const [prompt,setPrompt]=useState(''); const [pending,setPending]=useState<StudioStagedImport|null>(null);const [nativeMediaStatus,setNativeMediaStatus]=useState<StudioStagedImport|null>(null); const [error,setError]=useState('');const [previewSeconds,setPreviewSeconds]=useState(20);const [draftConsent,setDraftConsent]=useState(false);const [operation,setOperation]=useState<Operation>('Author');const [reviewTargets,setReviewTargets]=useState('');const [editable,setEditable]=useState('');const [editablePaths,setEditablePaths]=useState('');const [findingScope,setFindingScope]=useState('');const [reviewMediaKind,setReviewMediaKind]=useState<'preview'|'film'|'voice'|'captions'>('preview');const [reviewFolder,setReviewFolder]=useState('');const [transferAcknowledged,setTransferAcknowledged]=useState(false);const [approvalNote,setApprovalNote]=useState(''); const stage=tab.toLowerCase();const lifecycleOperation=operation.toLowerCase().replace(' ','-') as 'review'|'correct'|'recheck'|'media-review';const requests=useRef({freeze:0,validate:0,pending:0,confirm:0,export:0});const splitList=(value:string)=>value.split(',').map(x=>x.trim()).filter(Boolean);const lifecycleScope=()=>({targetIds:splitList(reviewTargets),editableIds:splitList(editable),editablePaths:splitList(editablePaths),findingIds:findingScope.trim()?splitList(findingScope):undefined,media:operation==='Media review'?reviewMediaKind:undefined,transferAcknowledged:operation==='Media review'?transferAcknowledged:undefined});const reviews=Object.values(native?.lifecycle?.artifacts??{}).filter(item=>item.stage===stage&&['review','recheck','media-review'].includes(item.operation)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const lastReview=reviews[0];const reviewFindings=((lastReview?.value??{}) as {findings?:Array<{id:string;severity:string;status:string;target_ids:string[];requirement:string}>}).findings??[];
  const projectId=native?.project.id;useEffect(()=>{setJson('');setResult('idle');setPending(null);setNativeMediaStatus(null);setPrompt('');setError('');setReviewFolder('');setTransferAcknowledged(false);setDraftConsent(false);},[projectId,setJson,setResult]);
  useEffect(()=>{setJson('');setResult('idle');setPending(null);setNativeMediaStatus(null);setPrompt('');setError('');setReviewFolder('');setReviewMediaKind(stage==='script'?'voice':'preview');setTransferAcknowledged(false);setDraftConsent(false);},[stage,operation,setJson,setResult]);
  useEffect(()=>{requests.current.validate+=1;requests.current.pending+=1;requests.current.confirm+=1;requests.current.export+=1;},[projectId,stage]);
  useEffect(()=>{const scope=captureProjectSession();const expectedStage=stage,expectedOperation=operation;const sequence=++requests.current.freeze;let active=true;if(native&&scope&&window.studio){const scopeInput=lifecycleScope();const request=operation==='Author'?window.studio.freezeTask(native.project.id,stage):window.studio.freezeLifecycle(native.project.id,stage,lifecycleOperation,scopeInput);request.then(value=>{if(active&&sequence===requests.current.freeze&&expectedStage===stage&&expectedOperation===operation&&isCurrentProjectSession(scope))setPrompt(value.prompt)}).catch(reason=>{if(active&&sequence===requests.current.freeze&&expectedStage===stage&&expectedOperation===operation&&isCurrentProjectSession(scope)){setError(String(reason));setPrompt('')}})}else setPrompt('');return()=>{active=false};},[native?.project.id,stage,operation,reviewMediaKind,reviewTargets,editable,editablePaths,findingScope,transferAcknowledged]);
  const change=(value:string)=>{setJson(value);setResult('idle');setPending(null);setNativeMediaStatus(null);setDraftConsent(false);setError('');};
  const refreshPending=async()=>{if(!native||!window.studio||stage!=='native')return;const scope=captureProjectSession(),expectedStage=stage,expectedOperation=operation,sequence=++requests.current.pending;if(!scope)return;try{const value=await window.studio.pendingMedia(native.project.id);if(!isCurrentProjectSession(scope)||expectedStage!==stage||expectedOperation!==operation||sequence!==requests.current.pending)return;if(operation==='Author')setPending(value);else setNativeMediaStatus(value);setError('');}catch(reason){if(isCurrentProjectSession(scope)&&expectedStage===stage&&expectedOperation===operation&&sequence===requests.current.pending)setError(String(reason));}};
  const validate=async()=>{const scope=captureProjectSession(),expectedStage=stage,expectedOperation=operation,sequence=++requests.current.validate;try{if(!native||!scope||!window.studio)throw new Error('Open a native project first.');const value=operation==='Author'?await window.studio.stageImport(native.project.id,expectedStage,json):await window.studio.stageLifecycle(native.project.id,expectedStage,lifecycleOperation,json);if(!isCurrentProjectSession(scope)||expectedStage!==stage||expectedOperation!==operation||sequence!==requests.current.validate)return;setPending(value);setNativeMediaStatus(null);setResult('valid');}catch(reason){if(scope&&(!isCurrentProjectSession(scope)||expectedStage!==stage||sequence!==requests.current.validate))return;setResult('invalid');setError(reason instanceof Error?reason.message:String(reason));}};
  const copy=()=>{const scope=captureProjectSession(),expectedStage=stage;if(!scope)return;void navigator.clipboard.writeText(prompt).then(()=>{if(isCurrentProjectSession(scope)&&expectedStage===stage)showNotice(`${tab} prompt copied.`)}).catch(reason=>{if(isCurrentProjectSession(scope)&&expectedStage===stage)setError('Clipboard ERROR: '+String(reason))})};
  const exportFile=async()=>{if(!native||!window.studio)return;const scope=captureProjectSession(),expectedStage=stage,sequence=++requests.current.export;if(!scope)return;try{const file=await window.studio.exportPrompt(native.project.id,expectedStage,operation==='Author'?'author':lifecycleOperation,lifecycleScope());if(file&&isCurrentProjectSession(scope)&&expectedStage===stage&&sequence===requests.current.export)showNotice('Prompt exported: '+file);}catch(reason){if(isCurrentProjectSession(scope)&&expectedStage===stage&&sequence===requests.current.export)setError(String(reason));}};
  const exportMediaPack=async()=>{if(!native||!window.studio)return;const scope=captureProjectSession();if(!scope)return;try{const kind=reviewMediaKind;const value=await window.studio.reviewPack(scope.projectId,kind);if(isCurrentProjectSession(scope))setReviewFolder(value.folder??value.path);}catch(reason){if(isCurrentProjectSession(scope))setError(String(reason));}};
  return <div className="grid wide-left"><Card><CardHeader title="External task prompt" hint="Copy to ChatGPT manually · no embedded API" action={<Badge tone={native&&prompt?'mint':'amber'}>{native&&prompt?'FROZEN':'EMPTY'}</Badge>}/><div className="tabs">{tabs.map(item=><button key={item} className={tab===item?'active':''} onClick={()=>setTab(item)}>{item}</button>)}</div><div className="tabs">{operations.map(item=><button key={item} className={operation===item?'active':''} onClick={()=>setOperation(item)}>{item}</button>)}</div>{['Review','Recheck','Media review'].includes(operation)&&<Field label="Review target IDs (optional; blank covers every section/shot)"><Input value={reviewTargets} onChange={event=>setReviewTargets(event.target.value)} placeholder="shot-001, shot-002"/></Field>}{operation==='Correct'&&<><Field label="Editable section/shot IDs (comma separated)"><Input value={editable} onChange={event=>setEditable(event.target.value)} placeholder="S03, S04"/></Field><Field label="Expanded editable field paths (optional, comma separated)"><Input value={editablePaths} onChange={event=>setEditablePaths(event.target.value)} placeholder="/manifest/opening, /sound_script/2"/></Field></>}{['Correct','Recheck'].includes(operation)&&<Field label="Finding IDs to resolve (optional; defaults to unresolved findings)"><Input value={findingScope} onChange={event=>setFindingScope(event.target.value)} placeholder="F-001, F-002"/></Field>}<pre className="prompt" data-active-prompt={tab}>{native?prompt:''}</pre>{!native&&<div className="info">EMPTY — Create/open a project to freeze a real ChatGPT task. No sample prompt is available.</div>}<div className="actions"><Button variant="primary" disabled={!native||!prompt} onClick={copy}>Copy prompt</Button><Button disabled={!native||!prompt} onClick={exportFile}>Export .md</Button>{operation==='Media review'&&<Field label="Review media scope"><select value={reviewMediaKind} onChange={event=>{setReviewMediaKind(event.target.value as 'preview'|'film'|'voice'|'captions');setReviewFolder('');setTransferAcknowledged(false);}}>{stage==='native'?<><option value="preview">Actual preview</option><option value="film">Encoded full film</option></>:<><option value="voice">Accepted narration WAV</option><option value="captions">Accepted captions</option></>}</select></Field>}{operation==='Media review'&&<Button disabled={!native} onClick={exportMediaPack}>Export actual media pack</Button>}{operation==='Media review'&&<label className="check"><input type="checkbox" checked={transferAcknowledged} onChange={event=>setTransferAcknowledged(event.target.checked)}/> I manually transferred this project's actual MP4/WAV and review JSON to External ChatGPT. This attestation is not proof the model inspected them.</label>}<Button onClick={()=>window.open('https://chatgpt.com/','_blank','noopener,noreferrer')}>Open ChatGPT</Button></div>{reviewFolder&&<div className="info">Transfer the actual files in {reviewFolder} together with review-package.json. Local files and hashes alone do not establish audiovisual inspection.</div>}{lastReview&&<div className="info"><strong>Latest {lastReview.operation}: {lastReview.status}</strong>{reviewFindings.length?reviewFindings.map(item=><div key={item.id}>{item.id} · {item.severity} · {item.status} · {item.target_ids.join(', ')} · {item.requirement}</div>):<div>No reported findings; this is not automatic creative approval.</div>}</div>}</Card>
    <Card><CardHeader title="Import JSON workspace" hint="Strict schema · diff · explicit confirmation"/><Textarea aria-label="Import JSON" value={json} onChange={event=>change(event.target.value)} placeholder="Paste the returned JSON here…"/><div className="actions"><Button disabled={!json} onClick={()=>change('')}>Clear</Button><Button variant="primary" disabled={!native||!json} onClick={validate}>Validate import</Button></div>
      {result==='valid'&&<div className="info success">Schema valid. Review the staged diff before import.</div>}{result==='invalid'&&<div className="info error" role="alert">Invalid import. {error}</div>}
      {pending&&<><div className="diff-grid"><pre className="prompt">BEFORE{`\n`}{JSON.stringify(pending.before,null,2)}</pre><pre className="prompt">AFTER{`\n`}{JSON.stringify(pending.after,null,2)}</pre></div>
        {stage==='native'&&<><div className="info">Original Mode B validates the selected sample with --seconds N. FULL_READY requires separate unscoped native validation. Media outside the scoped sample may remain incomplete only for an explicitly approved draft.</div>
          <Field label="Owner-selected preview seconds (1–60)"><Input type="number" min={1} max={60} value={previewSeconds} onChange={event=>setPreviewSeconds(Number(event.target.value))}/></Field>
          <label className="check"><input type="checkbox" checked={draftConsent} onChange={event=>setDraftConsent(event.target.checked)}/> I explicitly authorize an incomplete SAMPLE_READY draft, not full-film readiness.</label>
          <Button onClick={refreshPending}>Refresh missing media after mapping</Button>
          {(nativeMediaStatus??pending).missing?.length? <div className="info">Unresolved native targets: {(nativeMediaStatus??pending).missing.map(item=>item.key+' ('+item.path+')').join(', ')}. Select each precise target in Storyboard; only in-scope missing media blocks the sample.</div>:<div className="info success">No unresolved file targets recorded; the original scoped/full CLI will still verify native integrity.</div>}
        </>}
        <Button variant="primary" onClick={async()=>{if(!window.studio||!native)return;const scope=captureProjectSession(),expectedStage=stage,expectedOperation=operation,sequence=++requests.current.confirm;if(!scope)return;try{const state=operation==='Author'?await window.studio.confirmImport(scope.projectId,pending.token,expectedStage==='native'?{previewSeconds,allowSampleDraft:draftConsent}:undefined):await window.studio.confirmLifecycle(scope.projectId,pending.token,expectedStage==='native'&&expectedOperation==='Correct'?{previewSeconds,allowSampleDraft:draftConsent}:undefined);if(expectedStage!==stage||expectedOperation!==operation||sequence!==requests.current.confirm||!setNativeIfSessionCurrent(scope,state))return;setPending(null);setNativeMediaStatus(null);setError('');showNotice(operation==='Author'&&expectedStage==='native'?(state.nativeReadiness?.fullReady?'FULL_READY · original native validator PASS.':'SAMPLE_READY draft · not full render ready.'):`${tab} ${operation} imported; owner approval is separate.`);}catch(reason){if(!isCurrentProjectSession(scope)||expectedStage!==stage||sequence!==requests.current.confirm)return;setResult('invalid');setError(String(reason));}}}>Confirm reviewed import {operation==='Author'&&stage==='native'?'(original native CLI validation)':''}</Button>
      </>}
      {stage==='script'&&native?.scriptCandidate&&<div className="info"><strong>CANDIDATE revision {native.scriptCandidate.revision}</strong> · not approved for voice. <Input aria-label="Script approval note" value={approvalNote} onChange={event=>setApprovalNote(event.target.value)} placeholder="Owner approval note"/><Button variant="primary" disabled={!approvalNote.trim()} onClick={async()=>{if(!window.studio||!native)return;const scope=captureProjectSession();if(!scope)return;try{const state=await window.studio.approveScript(scope.projectId,approvalNote);if(setNativeIfSessionCurrent(scope,state)){setApprovalNote('');showNotice('APPROVED · exact Script candidate is now the production narration authority.')}}catch(reason){if(isCurrentProjectSession(scope))setError(String(reason))}}}>Approve exact Script candidate</Button></div>}{error&&result!=='invalid'&&<div className="info error" role="alert">{error}</div>}{native?.nativeReadiness&&<div className="info">Current native readiness: {native.nativeReadiness.fullReady?'FULL_READY':native.nativeReadiness.sampleReady?'SAMPLE_READY draft':'NOT_READY'} · verified range {native.nativeReadiness.checkedSeconds??'ERROR'}s · latest requested {native.nativeReadiness.previewSeconds}s.</div>}
      {!native&&<div className="info">Open a project to create and import an actual frozen task. No demo import is available.</div>}
    </Card></div>;
}
